package com.bridge.quartercore;
import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class FixedEIdleContinuationTest {
 @Test void writerOnlyOneOrTwoVerifiedPairsAndCompletionExactlyThree(){var base=FixedEIdleBaseline.snapshot();var bundle=FixedEBaselineBundle.compiledIdleContinuation();assertThrows(RuntimeException.class,()->bundle.requireNextClaim(base));var one=FixedERestartHttpSafetyTest.pair(base,"w-"+UUID.randomUUID());bundle.requireNextClaim(one);var two=FixedERestartHttpSafetyTest.pair(one,"w-"+UUID.randomUUID());bundle.requireNextClaim(two);var three=FixedERestartHttpSafetyTest.pair(two,"w-"+UUID.randomUUID());assertEquals(3,bundle.completedPairs(three));assertThrows(RuntimeException.class,()->bundle.requireNextClaim(three));for(var incomplete:List.of(base,one,two)){var a=FixedEVerifiedArtifact.completedIdleContinuation();assertThrows(RuntimeException.class,()->a.verifyOnce(()->incomplete));assertNull(a.response("GET",FixedEVerifiedArtifact.PATH,null));}var success=FixedEVerifiedArtifact.completedIdleContinuation();success.verifyOnce(()->three);assertNotNull(success.response("GET",FixedEVerifiedArtifact.PATH,null));assertThrows(RuntimeException.class,()->FixedEBaselineBundle.compiledIdleWake().completedPairs(three));assertNull(NativeRestartCompiledRelease.current());}
 @Test void noAssumedSeq20OrUnverifiedData(){var bundle=FixedEBaselineBundle.compiledIdleContinuation();var bad=FixedERestartHttpSafetyTest.pair(FixedEIdleBaseline.snapshot(),"w-"+UUID.randomUUID());bad.sheet("accounts").rows.get(1).set(1,"changed");assertThrows(RuntimeException.class,()->bundle.requireNextClaim(bad));assertThrows(RuntimeException.class,()->bundle.requireNextClaim(FixedECompiledBaseline.snapshot()));}
 @Test void independentFlagAndNoOverrides(){assertThrows(RuntimeException.class,()->FixedEBoundedRestartMain.requireContinuationConfiguration(Map.of("BRIDGE_FIXED_E_IDLE_WAKE_ENABLED","true","BRIDGE_READONLY_STARTUP_ENABLED","false")));var e=new HashMap<String,String>();e.put("BRIDGE_FIXED_E_IDLE_CONTINUATION_ENABLED","true");e.put("BRIDGE_READONLY_STARTUP_ENABLED","false");assertDoesNotThrow(()->FixedEBoundedRestartMain.requireContinuationConfiguration(e));e.put("BRIDGE_FIXED_E_BASELINE","claimed-seq20");assertThrows(RuntimeException.class,()->FixedEBoundedRestartMain.requireContinuationConfiguration(e));}
}
